1	/**
2	 * Encapsulates input data for LCS computation with validation.
3	 */
4	class LcsInput {
5	    private final String firstString;
6	    private final String secondString;
7	
8	    /**
9	     * Constructs an LcsInput with validation.
10	     *
11	     * @param firstString  the first string (non-null)
12	     * @param secondString the second string (non-null)
13	     * @throws IllegalArgumentException if firstString is null
14	     * @throws IllegalArgumentException if secondString is null
15	     */
16	    public LcsInput(String firstString, String secondString) {
17	        if (firstString == null) {
18	            throw new IllegalArgumentException("First string cannot be null");
19	        }
20	        if (secondString == null) {
21	            throw new IllegalArgumentException("Second string cannot be null");
22	        }
23	        this.firstString = firstString;
24	        this.secondString = secondString;
25	    }
26	
27	    public String getFirstString() {
28	        return firstString;
29	    }
30	
31	    public String getSecondString() {
32	        return secondString;
33	    }
34	}
