36	/**
37	 * Encapsulates the result of LCS computation.
38	 */
39	class LcsResult {
40	    private final int length;
41	
42	    public LcsResult(int length) {
43	        this.length = length;
44	    }
45	
46	    public int getLength() {
47	        return length;
48	    }
49	}
