1	/**
2	 * Shared utility for building DP (Dynamic Programming) tables.
3	 * Eliminates code duplication across multiple solver implementations.
4	 *
5	 * The DP table computes the length of LCS at each cell [i][j],
6	 * where dp[i][j] represents the LCS length of s1[0..i-1] and s2[0..j-1].
7	 */
8	class DpTableBuilder {
9	
10	    /**
11	     * Builds the DP table for LCS computation.
12	     *
13	     * Algorithm: Fill table left-to-right, top-to-bottom.
14	     * - If characters match: extend previous diagonal result
15	     * - If no match: take maximum of left or top cell
16	     *
17	     * @param s1 first string (non-null)
18	     * @param s2 second string (non-null)
19	     * @return DP table where dp[m][n] contains LCS length
20	     */
21	    static int[][] buildTable(String s1, String s2) {
22	        int m = s1.length();
23	        int n = s2.length();
24	        int[][] dpTable = new int[m + 1][n + 1];
25	
26	        for (int i = 1; i <= m; i++) {
27	            for (int j = 1; j <= n; j++) {
28	                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
29	                    dpTable[i][j] = dpTable[i - 1][j - 1] + 1;
30	                } else {
31	                    dpTable[i][j] = Math.max(dpTable[i - 1][j],
32	                                              dpTable[i][j - 1]);
33	                }
34	            }
35	        }
36	
37	        return dpTable;
38	    }
39	
40	    /**
41	     * Builds a DP table using a custom character matcher.
42	     * Enables case-insensitive, unicode-aware, or custom comparison logic.
43	     *
44	     * @param s1 first string (non-null)
45	     * @param s2 second string (non-null)
46	     * @param matcher custom character comparison function
47	     * @return DP table where dp[m][n] contains LCS length
48	     */
49	    static int[][] buildTableWithMatcher(String s1, String s2, CharacterMatcher matcher) {
50	        int m = s1.length();
51	        int n = s2.length();
52	        int[][] dpTable = new int[m + 1][n + 1];
53	
54	        for (int i = 1; i <= m; i++) {
55	            for (int j = 1; j <= n; j++) {
56	                if (matcher.matches(s1.charAt(i - 1), s2.charAt(j - 1))) {
57	                    dpTable[i][j] = dpTable[i - 1][j - 1] + 1;
58	                } else {
59	                    dpTable[i][j] = Math.max(dpTable[i - 1][j],
60	                                              dpTable[i][j - 1]);
61	                }
62	            }
63	        }
64	
65	        return dpTable;
66	    }
67	}
