1	/**
2	 * Space-optimized LCS solver using rolling array technique.
3	 * Reduces space complexity from O(m*n) to O(min(m,n)) at the cost of
4	 * making sequence reconstruction impossible.
5	 *
6	 * Ideal for cases where only the length is needed and memory is a constraint.
7	 */
8	class SpaceOptimizedLcsSolver implements LcsSolver {
9	
10	    /**
11	     * Computes the length of the Longest Common Subsequence using space-optimized DP.
12	     * Time complexity: O(m * n), Space complexity: O(min(m, n))
13	     *
14	     * Strategy: Use two 1D arrays (previous row and current row) instead of 2D table.
15	     * Since DP recurrence only depends on the previous row and current position,
16	     * we can compute column by column using only two rows of storage.
17	     *
18	     * @param input the LcsInput containing two strings
19	     * @return LcsResult with the length of the LCS
20	     */
21	    @Override
22	    public LcsResult solve(LcsInput input) {
23	        String s1 = input.getFirstString();
24	        String s2 = input.getSecondString();
25	
26	        int m = s1.length();
27	        int n = s2.length();
28	
29	        // Optimize space by using the shorter string as the inner dimension
30	        if (m < n) {
31	            return solveOptimized(s1, s2);
32	        } else {
33	            return solveOptimized(s2, s1);
34	        }
35	    }
36	
37	    /**
38	     * Internal optimized solve ensuring s1 is the shorter string.
39	     *
40	     * @param s1 shorter string
41	     * @param s2 longer string
42	     * @return LcsResult with the length of the LCS
43	     */
44	    private LcsResult solveOptimized(String s1, String s2) {
45	        int m = s1.length();
46	        int n = s2.length();
47	
48	        // Two rows: previous and current
49	        int[] previousRow = new int[m + 1];
50	        int[] currentRow = new int[m + 1];
51	
52	        for (int j = 1; j <= n; j++) {
53	            for (int i = 1; i <= m; i++) {
54	                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
55	                    currentRow[i] = previousRow[i - 1] + 1;
56	                } else {
57	                    currentRow[i] = Math.max(previousRow[i], currentRow[i - 1]);
58	                }
59	            }
60	
61	            // Swap rows: current becomes previous for next iteration
62	            int[] temp = previousRow;
63	            previousRow = currentRow;
64	            currentRow = temp;
65	        }
66	
67	        // Result is in previousRow[m] (after final swap)
68	        return new LcsResult(previousRow[m]);
69	    }
70	}
