1	/**
2	 * Reusable assertion helpers for LCS testing.
3	 * Consolidates common test patterns and improves test readability.
4	 */
5	class TestAssertions {
6	
7	    /**
8	     * Asserts that LCS length is valid (non-negative and within bounds).
9	     * LCS length should always satisfy: 0 ≤ lcs_length ≤ min(len(s1), len(s2))
10	     *
11	     * @param lcsLength the computed LCS length
12	     * @param s1Length  length of first string
13	     * @param s2Length  length of second string
14	     */
15	    static void assertValidLcsLength(int lcsLength, int s1Length, int s2Length) {
16	        assert lcsLength >= 0 :
17	                "LCS length cannot be negative, got: " + lcsLength;
18	
19	        int minLength = Math.min(s1Length, s2Length);
20	        assert lcsLength <= minLength :
21	                String.format("LCS length (%d) exceeds min string length (%d)",
22	                        lcsLength, minLength);
23	    }
24	
25	    /**
26	     * Asserts that two LCS lengths are equal (for symmetry testing).
27	     * LCS(s1, s2) should always equal LCS(s2, s1).
28	     *
29	     * @param s1ToS2 LCS length of (s1, s2)
30	     * @param s2ToS1 LCS length of (s2, s1)
31	     * @param s1     first string (for error message)
32	     * @param s2     second string (for error message)
33	     */
34	    static void assertSymmetric(int s1ToS2, int s2ToS1, String s1, String s2) {
35	        assert s1ToS2 == s2ToS1 :
36	                String.format("Symmetry violated: LCS('%s','%s')=%d but LCS('%s','%s')=%d",
37	                        s1, s2, s1ToS2, s2, s1, s2ToS1);
38	    }
39	
40	    /**
41	     * Asserts that an exception of expected type is thrown with expected message.
42	     *
43	     * @param action                  runnable that should throw exception
44	     * @param expectedExceptionType   type of exception expected
45	     * @param expectedMessageContent  substring that should appear in exception message
46	     */
47	    static void assertThrowsWithMessage(
48	            Runnable action,
49	            Class<? extends Exception> expectedExceptionType,
50	            String expectedMessageContent) {
51	        try {
52	            action.run();
53	            assert false :
54	                    "Expected " + expectedExceptionType.getSimpleName() + " to be thrown";
55	        } catch (Exception e) {
56	            assert expectedExceptionType.isInstance(e) :
57	                    "Wrong exception type. Expected: " + expectedExceptionType.getName() +
58	                            ", Got: " + e.getClass().getName();
59	
60	            assert e.getMessage() != null && e.getMessage().contains(expectedMessageContent) :
61	                    "Exception message doesn't contain '" + expectedMessageContent + "'. " +
62	                            "Got: '" + e.getMessage() + "'";
63	        }
64	    }
65	
66	    /**
67	     * Asserts that two solvers produce identical results.
68	     * Useful for comparing different implementations or variants.
69	     *
70	     * @param solver1 first solver
71	     * @param solver2 second solver
72	     * @param input   input to both solvers
73	     */
74	    static void assertSolversMatch(LcsSolver solver1, LcsSolver solver2, LcsInput input) {
75	        int result1 = solver1.solve(input).getLength();
76	        int result2 = solver2.solve(input).getLength();
77	
78	        assert result1 == result2 :
79	                String.format("Solvers diverged: %s returned %d, %s returned %d",
80	                        solver1.getClass().getSimpleName(), result1,
81	                        solver2.getClass().getSimpleName(), result2);
82	    }
83	
84	    /**
85	     * Asserts that three solvers all produce the same result.
86	     * Useful for validating standard, optimized, and cached variants.
87	     *
88	     * @param solver1 first solver
89	     * @param solver2 second solver
90	     * @param solver3 third solver
91	     * @param input   input to all solvers
92	     */
93	    static void assertAllSolversMatch(LcsSolver solver1, LcsSolver solver2,
94	                                       LcsSolver solver3, LcsInput input) {
95	        int result1 = solver1.solve(input).getLength();
96	        int result2 = solver2.solve(input).getLength();
97	        int result3 = solver3.solve(input).getLength();
98	
99	        assert result1 == result2 && result2 == result3 :
100	                String.format("Solvers diverged: %d, %d, %d",
101	                        result1, result2, result3);
102	    }
103	
104	    /**
105	     * Asserts that LCS computation matches its reconstruction.
106	     * The length of the reconstructed LCS should equal the computed length.
107	     *
108	     * @param computedLength the LCS length from solver
109	     * @param reconstructed  the reconstructed LCS string
110	     */
111	    static void assertReconstructionMatches(int computedLength, String reconstructed) {
112	        assert reconstructed.length() == computedLength :
113	                String.format("Length mismatch: computed=%d, reconstructed length=%d",
114	                        computedLength, reconstructed.length());
115	    }
116	
117	    /**
118	     * Asserts that a string is a subsequence of another.
119	     * Used to verify that reconstructed LCS is actually a subsequence of both inputs.
120	     *
121	     * @param subsequence the supposed subsequence
122	     * @param string      the string to check against
123	     */
124	    static void assertIsSubsequence(String subsequence, String string) {
125	        int subIdx = 0;
126	        for (int i = 0; i < string.length() && subIdx < subsequence.length(); i++) {
127	            if (string.charAt(i) == subsequence.charAt(subIdx)) {
128	                subIdx++;
129	            }
130	        }
131	        assert subIdx == subsequence.length() :
132	                "'" + subsequence + "' is not a subsequence of '" + string + "'";
133	    }
134	
135	    /**
136	     * Asserts that two strings are common subsequences (appear in both with same order).
137	     *
138	     * @param lcs first string
139	     * @param s1  second string
140	     * @param s2  third string
141	     */
142	    static void assertCommonSubsequence(String lcs, String s1, String s2) {
143	        assertIsSubsequence(lcs, s1);
144	        assertIsSubsequence(lcs, s2);
145	    }
146	}
