1	/**
2	 * Extends LCS capability to reconstruct the actual longest common subsequence string.
3	 * This class maintains the full DP table to enable backtracking through the solution.
4	 */
5	class LcsSequenceReconstructor {
6	    /**
7	     * Reconstructs the actual LCS string from two input strings.
8	     *
9	     * Algorithm:
10	     * 1. Compute DP table (same as standard LCS)
11	     * 2. Backtrack from dp[m][n] to dp[0][0], building result in reverse
12	     * 3. Reverse final result (more efficient than repeated insert(0, ...))
13	     *
14	     * Time complexity: O(m * n) for DP + O(m + n) for backtracking + O(k) for reverse
15	     *   where k = LCS length. Total: O(m * n) since k ≤ min(m,n)
16	     * Space complexity: O(m * n) for DP table + O(min(m,n)) for result
17	     *
18	     * Note: Using append + reverse is O(n) total vs insert(0,...) which is O(n²)
19	     *       for LCS of length n due to repeated character shifting.
20	     *
21	     * @param s1 first string
22	     * @param s2 second string
23	     * @return the LCS string
24	     * @throws IllegalArgumentException if either string is null
25	     */
26	    public static String reconstructLcs(String s1, String s2) {
27	        if (s1 == null) {
28	            throw new IllegalArgumentException("First string cannot be null");
29	        }
30	        if (s2 == null) {
31	            throw new IllegalArgumentException("Second string cannot be null");
32	        }
33	
34	        int m = s1.length();
35	        int n = s2.length();
36	
37	        // Build DP table using shared utility
38	        int[][] dpTable = DpTableBuilder.buildTable(s1, s2);
39	
40	        // Backtrack to reconstruct the sequence
41	        // Build in reverse order for O(1) append instead of O(n) insert
42	        StringBuilder lcs = new StringBuilder();
43	        int i = m;
44	        int j = n;
45	
46	        while (i > 0 && j > 0) {
47	            // If characters match, include in result and move diagonally
48	            if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
49	                lcs.append(s1.charAt(i - 1));
50	                i--;
51	                j--;
52	            }
53	            // Otherwise, move in the direction of the larger value
54	            else if (dpTable[i - 1][j] > dpTable[i][j - 1]) {
55	                i--;
56	            } else {
57	                j--;
58	            }
59	        }
60	
61	        // Reverse to get correct order (we built it backwards for efficiency)
62	        return lcs.reverse().toString();
63	    }
64	
65	    /**
66	     * Convenience method using LcsInput.
67	     *
68	     * @param input the LcsInput containing two strings
69	     * @return the LCS string
70	     */
71	    public static String reconstructLcs(LcsInput input) {
72	        return reconstructLcs(input.getFirstString(), input.getSecondString());
73	    }
74	}
