1	import java.util.Objects;
2	
3	/**
4	 * Robust cache key for LCS computation results.
5	 * Normalizes string pairs to enable symmetric caching (handles both (A,B) and (B,A)).
6	 *
7	 * Uses length-prefixed encoding to prevent collisions from delimiter ambiguity.
8	 */
9	class CacheKey {
10	    private final String s1;
11	    private final String s2;
12	    private final int hashCode;
13	
14	    /**
15	     * Creates a normalized cache key from two strings.
16	     * Automatically sorts strings lexicographically for symmetry.
17	     *
18	     * @param s1 first string
19	     * @param s2 second string
20	     */
21	    CacheKey(String s1, String s2) {
22	        // Normalize order for symmetry: always use same ordering
23	        if (s1.compareTo(s2) <= 0) {
24	            this.s1 = s1;
25	            this.s2 = s2;
26	        } else {
27	            this.s1 = s2;
28	            this.s2 = s1;
29	        }
30	        // Pre-compute hash for efficiency
31	        this.hashCode = Objects.hash(this.s1, this.s2);
32	    }
33	
34	    /**
35	     * Generates a string representation using length-prefixed encoding.
36	     * This prevents collisions from cases like:
37	     *   ("AB||CD", "EF") vs ("AB", "||CD||EF")
38	     *
39	     * @return encoded cache key string
40	     */
41	    String getEncodedKey() {
42	        return s1.length() + ":" + s1 + "|" + s2.length() + ":" + s2;
43	    }
44	
45	    @Override
46	    public int hashCode() {
47	        return hashCode;
48	    }
49	
50	    @Override
51	    public boolean equals(Object o) {
52	        if (this == o) return true;
53	        if (!(o instanceof CacheKey)) return false;
54	        CacheKey other = (CacheKey) o;
55	        return s1.equals(other.s1) && s2.equals(other.s2);
56	    }
57	
58	    @Override
59	    public String toString() {
60	        return "CacheKey{" +
61	                "s1='" + s1 + '\'' +
62	                ", s2='" + s2 + '\'' +
63	                '}';
64	    }
65	}
