1	/**
2	 * Performance test demonstrating the improvement from using append+reverse
3	 * instead of insert(0, ...) in sequence reconstruction.
4	 */
5	class PerformanceTest {
6	
7	    /**
8	     * Simulates the OLD inefficient approach using insert(0, ...).
9	     * This is O(n²) because each insert shifts all existing characters.
10	     */
11	    static String reconstructOldWay(String s1, String s2) {
12	        int m = s1.length();
13	        int n = s2.length();
14	        int[][] dpTable = new int[m + 1][n + 1];
15	
16	        for (int i = 1; i <= m; i++) {
17	            for (int j = 1; j <= n; j++) {
18	                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
19	                    dpTable[i][j] = dpTable[i - 1][j - 1] + 1;
20	                } else {
21	                    dpTable[i][j] = Math.max(dpTable[i - 1][j], dpTable[i][j - 1]);
22	                }
23	            }
24	        }
25	
26	        StringBuilder lcs = new StringBuilder();
27	        int i = m;
28	        int j = n;
29	
30	        while (i > 0 && j > 0) {
31	            if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
32	                lcs.insert(0, s1.charAt(i - 1)); // O(n) operation!
33	                i--;
34	                j--;
35	            } else if (dpTable[i - 1][j] > dpTable[i][j - 1]) {
36	                i--;
37	            } else {
38	                j--;
39	            }
40	        }
41	
42	        return lcs.toString();
43	    }
44	
45	    /**
46	     * NEW efficient approach using append + reverse.
47	     * This is O(n) because append is O(1) amortized, and reverse is O(n).
48	     */
49	    static String reconstructNewWay(String s1, String s2) {
50	        return LcsSequenceReconstructor.reconstructLcs(s1, s2);
51	    }
52	
53	    public static void main(String[] args) {
54	        System.out.println("=== StringBuilder Performance Comparison ===\n");
55	
56	        String[][] testCases = {
57	                generateString('A', 100, 'B', 100),   // 100x100
58	                generateString('A', 500, 'B', 500),   // 500x500
59	                generateString('A', 1000, 'B', 1000), // 1000x1000
60	        };
61	
62	        for (String[] pair : testCases) {
63	            String s1 = pair[0];
64	            String s2 = pair[1];
65	
66	            System.out.println("Test: " + s1.length() + "x" + s2.length() + " strings");
67	
68	            // Time the old way
69	            long startOld = System.nanoTime();
70	            String resultOld = reconstructOldWay(s1, s2);
71	            long timeOld = System.nanoTime() - startOld;
72	
73	            // Time the new way
74	            long startNew = System.nanoTime();
75	            String resultNew = reconstructNewWay(s1, s2);
76	            long timeNew = System.nanoTime() - startNew;
77	
78	            // Verify correctness
79	            assert resultOld.equals(resultNew) :
80	                    "Results differ! Old: " + resultOld + ", New: " + resultNew;
81	
82	            double ratio = (double) timeOld / timeNew;
83	            System.out.printf("  Old way (insert):  %,d ns%n", timeOld);
84	            System.out.printf("  New way (reverse): %,d ns%n", timeNew);
85	            System.out.printf("  Improvement:       %.1fx faster%n\n", ratio);
86	        }
87	    }
88	
89	    private static String[] generateString(char c1, int len1, char c2, int len2) {
90	        StringBuilder s1 = new StringBuilder();
91	        StringBuilder s2 = new StringBuilder();
92	
93	        for (int i = 0; i < len1; i++) {
94	            s1.append(c1);
95	        }
96	        for (int i = 0; i < len2; i++) {
97	            s2.append(c2);
98	        }
99	
100	        return new String[]{s1.toString(), s2.toString()};
101	    }
102	}
